level: 3
parent_spec:
  name: "sources"
  url: "https://raw.githubusercontent.com/cogNNitive/cogNNitive-web/main/iNNfo/specs/bluepriNNts/sources/spec_NN.md"
knowledge_version: "V_0-1-0"
